\mathsf{WfRCtx}_{R}
=\{(x_1:_{r_1}A_1,\ldots,x_n:_{r_n}A_n):
n\in\mathbb N,\ x_i\ne x_j\ (i\ne j),\ r_i\in R,\ A_i\in\mathsf{Ty}_{R}\},

(\Delta_1\oplus\Delta_2)(x)=
\begin{cases}
x:_{r+s}A,&\Delta_1(x)=x:_{r}A\text{ 且 }\Delta_2(x)=x:_{s}A,\\
\Delta_1(x),&x\in dom(\Delta_1)\setminus dom(\Delta_2),\\
\Delta_2(x),&x\in dom(\Delta_2)\setminus dom(\Delta_1).
\end{cases}

\mathsf{ResEqCert}_{R}
=\{(D,\ell):D\subseteq_{\mathrm{fin}}\mathbb N^{<\omega},
\ell:D\to R\times R,\ \text{每个节点匹配 }\mathsf{ResEqStep}_{R}\}.
